/**
 * How Two cedars in a circle (`maru-ni-nihon-sugi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/maru-ni-nihon-sugi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Strike a ring outside the two vertical trunks. Give both cedars the same lance-shaped crown and leave a narrow opening between them.","ja":"二本のまっすぐな幹を囲む輪を打ちます。同じ形の細長い樹冠を並べ、その間に細いすき間を残します。"};

export default construction;
export { construction, description };
